const fit = {"minX":-0.4110746730774235,"maxY":0.3434506826858279,"scale":848.5323437889926,"left":129.0126411307965,"top":24};
export function projectChinaPoint(lon: number, lat: number): [number, number] {
  const radians = Math.PI / 180;
  const n = (Math.sin(25 * radians) + Math.sin(47 * radians)) / 2;
  const c = Math.cos(25 * radians) ** 2 + 2 * n * Math.sin(25 * radians);
  const rho0 = Math.sqrt(c - 2 * n * Math.sin(35 * radians)) / n;
  const rho = Math.sqrt(c - 2 * n * Math.sin(lat * radians)) / n;
  const theta = n * (lon - 105) * radians;
  return [fit.left + (rho * Math.sin(theta) - fit.minX) * fit.scale, fit.top + (fit.maxY - (rho0 - rho * Math.cos(theta))) * fit.scale];
}
